  /** The value, of the type the definition says */
  readonly value: unknown;
  /** When the value starts to hold */
  readonly validFrom: Timestamp;
  /** When it stops, where it does */
  readonly validTo: Timestamp | null;
  /** When it was last asserted */
  readonly updatedAt: Timestamp;
  /** Who asserted it, where a principal did */
