/** A rule of attribute-based access: a condition over attributes that allows or refuses an action; a refusal always wins */
export interface AccessPolicyRow {
  /** What identifies the policy, made by the application */
  readonly accessPolicyId: string;
  /** What the policy is called */
  readonly name: string;
  /** What the policy is for */
  readonly definition: string;
  /** What it decides */
  readonly effect: "allow" | "deny";
  /** The kind of principal it is about; every kind where it is empty */
  readonly appliesTo: "user" | "machine" | "device" | "agent" | "group" | null;
  /** The permission it is about: exact, or a prefix ending `*` */
  readonly actionPattern: string;
  /** The kind of resource it is about */
  readonly resourceType: string | null;
  /** When it applies, written in its language */
  readonly expression: string;
  /** The language of the condition */
  readonly expressionLanguageCode: string;
  /** What must happen before an allowed action is done */
  readonly obligation: "none" | "step_up" | "approval";
  /** The order policies are evaluated and explained in; a refusal wins whatever it is */
  readonly priority: number;
  /** Whether it is applied */
  readonly status: "active" | "retired";
  /** Which version of the policy this is */
  readonly version: number;
  /** When it starts to apply */
  readonly validFrom: Timestamp | null;
  /** When it stops */
  readonly validTo: Timestamp | null;
  /** A hash of the tenant, the name and the version, unique */
  readonly policyKey: string;
  /** The tenant it is for; empty for the platform's */
  readonly tenantId: string | null;
  /** The principal or group it is scoped to */
  readonly scopePrincipalPrincipalId: string | null;
  /** A role a principal must also hold for the policy to allow */
  readonly requiresRoleAccessRoleRoleId: string | null;
  /** The permission it is about, where it is about exactly one */
  readonly permissionId: string | null;
}

/** What an insert into access_policy takes: what the database fills may be left out. */
export interface AccessPolicyInsert {
  readonly accessPolicyId: string;
  readonly name: string;
  readonly definition: string;
  readonly effect: "allow" | "deny";
  readonly appliesTo?: "user" | "machine" | "device" | "agent" | "group" | null;
  readonly actionPattern: string;
  readonly resourceType?: string | null;
  readonly expression: string;
  readonly expressionLanguageCode: string;
  readonly obligation: "none" | "step_up" | "approval";
  readonly priority: number;
  readonly status: "active" | "retired";
  readonly version: number;
  readonly validFrom?: Timestamp | null;
  readonly validTo?: Timestamp | null;
  readonly policyKey: string;
  readonly tenantId?: string | null;
  readonly scopePrincipalPrincipalId?: string | null;
  readonly requiresRoleAccessRoleRoleId?: string | null;
  readonly permissionId?: string | null;
}

/** The key of a row of access_policy. */
export type AccessPolicyKey = { readonly accessPolicyId: string };

/** A rule of attribute-based access: a condition over attributes that allows or refuses an action; a refusal always wins */
export const accessPolicy = defineTable<AccessPolicyRow, AccessPolicyInsert, "accessPolicy">({
  alias: "accessPolicy",
  name: "access_policy",
  columns: {
    accessPolicyId: "access_policy_id",
    name: "name",
    definition: "definition",
    effect: "effect",
    appliesTo: "applies_to",
    actionPattern: "action_pattern",
    resourceType: "resource_type",
    expression: "expression",
    expressionLanguageCode: "expression_language_code",
    obligation: "obligation",
    priority: "priority",
    status: "status",
    version: "version",
    validFrom: "valid_from",
    validTo: "valid_to",
    policyKey: "policy_key",
    tenantId: "tenant_id",
    scopePrincipalPrincipalId: "scope_principal_principal_id",
    requiresRoleAccessRoleRoleId: "requires_role_access_role_role_id",
    permissionId: "permission_id",
  },
  primaryKey: ["accessPolicyId"],
  foreignKeys: [
    { columns: ["expressionLanguageCode"], references: "expressionLanguage", referencesColumns: ["code"] },
    { columns: ["tenantId"], references: "tenant", referencesColumns: ["tenantId"] },
    { columns: ["scopePrincipalPrincipalId"], references: "principal", referencesColumns: ["principalId"] },
    { columns: ["requiresRoleAccessRoleRoleId"], references: "accessRole", referencesColumns: ["roleId"] },
    { columns: ["permissionId"], references: "permission", referencesColumns: ["permissionId"] },
  ],
});
